import {paged} from './admin-operations.js';
import * as C from './core.js';
import {SOCIAL_FIELDS,socialConfig,saveSocialSettings,currentId} from './social-core.js';
import {saveGuildEvent,eventState,GUILD_ROLES} from './guilds.js';
import {moderateMessage,mutePilot} from './chat.js';
export function createSocialAdmin(env){const {escape:esc,input,textarea,button:btn,icon:I,assetUrl,modal}=env;const pages={events:1,guilds:1,listings:1,trades:1,messages:1};
 function pagination(collection,data){return `<div class="admin-pagination"><span>${data.total} registros · Página ${data.page}/${data.pages}</span><div>${btn('Anterior','admin-social-page',`data-collection="${collection}" data-id="${data.page-1}" ${data.page===1?'disabled':''}`,'secondary')}${btn('Próxima','admin-social-page',`data-collection="${collection}" data-id="${data.page+1}" ${data.page===data.pages?'disabled':''}`,'secondary')}</div></div>`;}
 function trades(s){const data=paged(s.social.trades,pages.trades);return `<div class="section-title"><h2>Transferências concluídas</h2></div><div class="table-wrap"><table><thead><tr><th>Participantes</th><th>Robôs</th><th>Valor / taxa</th><th>Data</th></tr></thead><tbody>${data.items.map(t=>`<tr><td>${esc(t.sellerId)} → ${esc(t.buyerId)}</td><td>${esc(t.robotUid)}${t.otherUid?' ⇄ '+esc(t.otherUid):''}</td><td>${t.priceLC} LC · ${t.feeLC} LC de taxa</td><td>${new Date(t.at).toLocaleDateString('pt-BR')}</td></tr>`).join('')||'<tr><td colspan="4">Nenhuma transferência registrada.</td></tr>'}</tbody></table></div>${pagination('trades',data)}`;}
 function render(tab){const s=env.getState(),cfg=socialConfig(s);if(!env.isDemo&&!s.social)return '<div class="notice">Conecte os endpoints sociais administrativos para carregar os dados do servidor.</div>';
  const eventPage=paged(s.social.events,pages.events),guildPage=paged(s.social.guilds,pages.guilds),listingPage=paged(s.social.listings,pages.listings),messagePage=paged(s.social.messages,pages.messages);
  const keys=tab==='guild-admin'?SOCIAL_FIELDS.filter(([k])=>k.startsWith('guild')):tab==='trade-admin'?SOCIAL_FIELDS.filter(([k])=>k.startsWith('trade')):SOCIAL_FIELDS.filter(([k])=>k.startsWith('chat')),flag=tab==='guild-admin'?'guildEnabled':tab==='trade-admin'?'tradeEnabled':'chatEnabled';
  return `<form id="admin-social-form" class="admin-form" data-flag="${flag}"><section><h3>${I(tab==='guild-admin'?'shield':tab==='trade-admin'?'shop':'users')} ${tab==='guild-admin'?'Guildas, convites e recompensas':tab==='trade-admin'?'Mercado e taxas':'Chat e moderação'}</h3><label class="checkbox"><input type="checkbox" name="${flag}" ${cfg[flag]?'checked':''}> Sistema disponível</label>${tab==='chat-admin'?`<label class="checkbox"><input type="checkbox" name="chatFloatingEnabled" ${cfg.chatFloatingEnabled?'checked':''}> Chat flutuante disponível no jogo</label><label class="checkbox"><input type="checkbox" name="chatStartMinimized" ${cfg.chatStartMinimized?'checked':''}> Iniciar minimizado para novos pilotos</label>`:''}${tab==='guild-admin'?`<label class="checkbox"><input type="checkbox" name="guildInviteOncePerPilot" ${cfg.guildInviteOncePerPilot?'checked':''}> Convites premiados apenas na primeira guilda do piloto</label>`:''}<div class="form-grid">${keys.map(([key,label,value,min,max])=>input(label,key,cfg[key]??value,'number',`min="${min}" max="${max}" step="${key==='tradeFeePercent'?'0.01':'1'}" required`)).join('')}</div><p>Contratos de oferta, recompensa e evento em andamento preservam a configuração usada ao criar. As alterações valem em novas operações.</p><button class="btn primary" type="submit">Salvar configurações</button></section></form>${tab==='guild-admin'?`<div class="section-title"><h2>Eventos com período</h2>${btn(I('plus')+' Criar evento','admin-event-edit','data-id="new"')}</div><div class="admin-catalog">${eventPage.items.map(def=>{const e=eventState(s,def.id);return `<article><img class="admin-event-thumb" src="${assetUrl(e.scene+'.png')}" alt="${esc(e.name)}"><div><h3>${esc(e.name)}</h3><p>${new Date(e.startsAt).toLocaleDateString('pt-BR')} → ${new Date(e.endsAt).toLocaleDateString('pt-BR')} · ${e.phase}</p><small>Pool ${e.rewardPoolRC} RC · Participação ${e.participationRC} RC · Vitória ${e.battleRewardRC} RC</small></div>${btn('Editar','admin-event-edit',`data-id="${def.id}"`,'secondary')}${env.isDemo&&e.phase==='active'&&s.social.eventSnapshots[e.id]?btn('Encerrar teste','admin-event-end-demo',`data-id="${e.id}"`,'text'):''}</article>`;}).join('')}</div>${pagination('events',eventPage)}<div class="section-title"><h2>Guildas e hierarquia</h2></div><div class="admin-catalog">${guildPage.items.map(g=>`<article><img class="admin-guild-crest" src="${assetUrl('guild-crest.png')}" alt="Brasão"><div><h3>[${esc(g.tag)}] ${esc(g.name)}</h3><p>NV. ${g.level} · ${g.xp} XP · ${g.members.length} membros</p><small>${g.members.map(m=>GUILD_ROLES[m.role]).join(' / ')}</small></div>${btn('Ver membros','guild-roster',`data-id="${g.id}"`,'secondary')}</article>`).join('')}</div>${pagination('guilds',guildPage)}`:tab==='trade-admin'?`<div class="section-title"><h2>Ofertas e transações</h2><span>${s.social.listings.length} ofertas</span></div><div class="table-wrap"><table><thead><tr><th>Oferta</th><th>Tipo / valor</th><th>Status</th><th>Data</th></tr></thead><tbody>${listingPage.items.map(l=>`<tr><td>${esc(l.id)}<small class="cell-sub">Robô ${esc(l.robotUid)}</small></td><td>${l.kind} · ${l.priceLC} LC</td><td>${l.status}</td><td>${new Date(l.createdAt).toLocaleDateString('pt-BR')}</td></tr>`).join('')}</tbody></table></div>${pagination('listings',listingPage)}${trades(s)}`:`<div class="section-title"><h2>Mensagens recentes</h2></div><div class="admin-chat-messages">${messagePage.items.map(m=>`<article><div><small>${esc(m.room)} · ${esc(m.name)}</small><p>${esc(m.text)}</p></div>${btn('Remover mensagem','admin-chat-remove',`data-id="${m.id}"`,'text')}</article>`).join('')}</div>${pagination('messages',messagePage)}<form id="admin-chat-mute" class="admin-form"><section><h3>Suspender envio de mensagens</h3><div class="form-grid"><label class="form-field"><span>Piloto</span><select name="userId">${[s.profile,...s.adminAccounts.map(a=>a.profile)].map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>${input('Minutos (0 = liberar)','minutes',30,'number','min="0" max="43200" required')}</div><button class="btn secondary" type="submit">Aplicar moderação</button></section></form>`}`;
 }
 function editEvent(id){const s=env.getState(),cfg=socialConfig(s),e=s.social.events.find(e=>e.id===id)||{id:'new',name:'Novo confronto',description:'Um novo farol aguarda sua guilda.',startsAt:Date.now()+C.DAY,endsAt:Date.now()+(cfg.guildEventDays+1)*C.DAY,scene:'guild-canyon',enabled:true,rewardPoolRC:cfg.guildPrizePoolRC,participationRC:cfg.guildParticipationRC,battleRewardRC:cfg.guildBattleRewardRC};const local=value=>{const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  modal(`<h2 id="modal-title">${id==='new'?'Nova edição de evento':'Editar edição de evento'}</h2><form id="admin-event-form" data-id="${e.id}">${input('Nome','name',e.name,'text','required maxlength="80"')}${textarea('Descrição','description',e.description)}<div class="form-grid">${input('Início','startsAt',local(e.startsAt),'datetime-local','required')}${input('Duração em dias','durationDays',Math.max(1,Math.round((e.endsAt-e.startsAt)/C.DAY)),'number','min="1" max="90" required')}<label class="form-field"><span>Mapa de guerra</span><select name="scene"><option value="guild-canyon" ${e.scene==='guild-canyon'?'selected':''}>Cânion do Farol</option><option value="guild-boreal" ${e.scene==='guild-boreal'?'selected':''}>Bastião Boreal</option></select></label>${['rewardPoolRC','participationRC','battleRewardRC'].map(k=>input({rewardPoolRC:'Pool da vencedora RC',participationRC:'Participação por piloto RC',battleRewardRC:'Vitória individual RC'}[k],k,e[k],'number','min="0" required')).join('')}</div><label class="checkbox"><input name="enabled" type="checkbox" ${e.enabled?'checked':''}> Evento disponível</label><p>Uma edição com participação já registrada preserva seu contrato. Crie uma nova edição para mudar datas ou prêmios.</p><button class="btn primary wide" type="submit">Salvar evento</button></form>`,'large');
 }
 async function submit(f,v){if(f.id==='admin-social-form'){const next={...socialConfig(env.getState())};for(const [key] of SOCIAL_FIELDS)if(Object.hasOwn(v,key))next[key]=Number(v[key]);next[f.dataset.flag]=v[f.dataset.flag]==='on';if(f.dataset.flag==='chatEnabled'){next.chatFloatingEnabled=v.chatFloatingEnabled==='on';next.chatStartMinimized=v.chatStartMinimized==='on';}if(f.dataset.flag==='guildEnabled')next.guildInviteOncePerPilot=v.guildInviteOncePerPilot==='on';await env.mutate(s=>saveSocialSettings(s,next),'Sistema configurado.',{action:'admin_social_settings',payload:{settings:next}});return true;}
  if(f.id==='admin-event-form'){const startsAt=new Date(v.startsAt).getTime(),event={id:f.dataset.id==='new'?C.uuid():f.dataset.id,type:'guild-war',name:v.name.trim(),description:v.description,startsAt,endsAt:startsAt+Number(v.durationDays)*C.DAY,scene:v.scene,enabled:v.enabled==='on',rewardPoolRC:Number(v.rewardPoolRC),participationRC:Number(v.participationRC),battleRewardRC:Number(v.battleRewardRC)};await env.mutate(s=>saveGuildEvent(s,event),'Edição de evento salva.',{action:'admin_guild_event_save',payload:{event}});return true;}
  if(f.id==='admin-chat-mute'){await env.mutate(s=>mutePilot(s,v.userId,Number(v.minutes)),'Moderação aplicada.',{action:'admin_chat_mute',payload:{user_id:v.userId,minutes:Number(v.minutes)}});return true;}
  return false;
 }
 return {render,editEvent,submit,setPage:(collection,page)=>{if(Object.hasOwn(pages,collection))pages[collection]=page;},handles:tab=>['guild-admin','trade-admin','chat-admin'].includes(tab),removeMessage:id=>env.mutate(s=>moderateMessage(s,id),'Mensagem removida.',{action:'admin_chat_remove',payload:{message_id:id}})};
}
